#!/usr/bin/env python3
"""Restore ALL SIRAJ work (d.16 + d.17 + d.18) from upstream/main reset."""
import base64, io, pathlib, sys, tarfile
DATA=""""""
def main():
    root=pathlib.Path.cwd()
    if not (root/"siraj_research"/"hooks.py").is_file():
        sys.exit("Run from ~/frappe-bench/apps/siraj_research")
    blob=base64.b64decode("".join(DATA.split()))
    with tarfile.open(fileobj=io.BytesIO(blob), mode="r:xz") as tf:
        names=tf.getnames()
        if any(n.startswith("/") or ".." in pathlib.PurePosixPath(n).parts for n in names):
            sys.exit("Unsafe archive")
        for n in names:
            p=root/n; p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(tf.extractfile(n).read())
    for rel in ["siraj_research/record_icons.py","siraj_research/public/js/siraj-record-meta.js","siraj_research/public/js/siraj-map/siraj-map.js"]:
        p=root/rel
        if p.exists():
            s=p.read_text()
            s=s.replace("hierarchy-ui.d.15","hierarchy-ui.d.18").replace("hierarchy-ui.d.17","hierarchy-ui.d.18")
            p.write_text(s)
    print("Restored d.16 + d.17 + d.18:",len(names),"files; stamps -> d.18")
    print("Next: bench --site frappe.com migrate && bench build --app siraj_research && bench --site frappe.com clear-cache")
    print("Then: bench --site frappe.com execute siraj_research.api.geo_package.export_offline_package")
if __name__=="__main__": main()
